#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maximumWealth(vector<vector<int>>& accounts) {
        int maxWealth = 0;
        for (auto& account : accounts) {
            int sum = accumulate(account.begin(), account.end(), 0);
            maxWealth = max(maxWealth, sum);
        }
        return maxWealth;
    }
};
